const faqSearch=document.querySelector('#help-search'),faqFilters=[...document.querySelectorAll('[data-category][aria-pressed]')],faqItems=[...document.querySelectorAll('.faq-items details')],faqGroups=[...document.querySelectorAll('.faq-group')];
let faqCategory='All questions';
function matchesFaq(category,text,selected,query){return(selected==='All questions'||category===selected)&&query.trim().toLocaleLowerCase().split(/\s+/).every(word=>text.toLocaleLowerCase().includes(word))}
function renderFaq(){let count=0;faqItems.forEach(item=>{const visible=matchesFaq(item.dataset.category,item.textContent,faqCategory,faqSearch.value);item.hidden=!visible;if(!visible)item.open=false;if(visible)count++});faqGroups.forEach(group=>group.hidden=![...group.querySelectorAll('details')].some(item=>!item.hidden));faqFilters.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.category===faqCategory)));document.querySelector('#help-empty').hidden=count>0;document.querySelector('#help-status').textContent=`${count} ${count===1?'answer':'answers'} found.`;requestAnimationFrame(window.FH.updateHeader)}
faqSearch.addEventListener('input',renderFaq);faqFilters.forEach(button=>button.addEventListener('click',()=>{faqCategory=button.dataset.category;renderFaq()}));
document.querySelector('#help-reset').addEventListener('click',()=>{faqCategory='All questions';faqSearch.value='';renderFaq();faqSearch.focus({preventScroll:true})});
faqItems.forEach(item=>{item.querySelector('summary').addEventListener('click',()=>{if(!item.open)faqItems.forEach(other=>{if(other!==item)other.open=false})});item.addEventListener('toggle',()=>{if(item.open)faqItems.forEach(other=>{if(other!==item)other.open=false});window.FH.updateHeader()})});renderFaq();
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.help-intro h1,.help-contact>div').forEach(el=>{el.classList.add('help-reveal');observer.observe(el)})}
